  sets['1.8'][45].steps.push(tr('Carry out A=YX⁻¹: row 1 gives (1×3+(−2)×(−1), 1×(−2)+(−2)×1)=(5,−4); row 2 gives ((−2)×3+5×(−1), (−2)×(−2)+5×1)=(−11,9).',"Beräkna A=YX⁻¹: rad 1 ger (1×3+(−2)×(−1), 1×(−2)+(−2)×1)=(5,−4); rad 2 ger ((−2)×3+5×(−1), (−2)×(−2)+5×1)=(−11,9)."));
